    private void mnuSis_SairActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_mnuSis_SairActionPerformed
        int resposta = JOptionPane.showConfirmDialog(this, "Deseja realmente encerrar o sistema?","Confirmação",JOptionPane.YES_NO_CANCEL_OPTION);
        if (resposta == JOptionPane.YES_OPTION){
            System.exit(0);
        }
    }//GEN-LAST:event_mnuSis_SairActionPerformed

